<template>    <div        class="day-popup"        @click="$emit('close')"    >        <div            class="inner"            @click.stop        >            <div                v-for="episode in content"                :key="episode._id"                class="episode"                :style="`background-image: url(${image(episode)})`"            >                {{ episode.serial.title }} - {{ episode.title }}            </div>        </div>    </div></template><script setup lang="ts">import {useRuntimeConfig} from "#app";import {computed} from "#imports";import type {ISerialEpisodeWithSerialInfo, TDay} from "~/appModules/calendar/calendarTypes";// Propsconst props = defineProps<{    dayData: TDay;}>();// Composablesconst config = useRuntimeConfig();// Computedconst content = computed((): ISerialEpisodeWithSerialInfo[] => {    return props.dayData?.content || [];});// Methodsfunction image(episode: ISerialEpisodeWithSerialInfo): string {    return `${config.public.cdnUrl}/serials/${episode.serial._id}.jpg`;}</script><style scoped lang="scss">.day-popup {    position: absolute;    top: 0;    right: 0;    bottom: 0;    left: 0;    display: flex;    align-items: center;    justify-content: center;    background-color: rgba(black, .5);}.inner {    width: 100%;    max-width: 500px;    padding: 20px;    border-radius: 10px;    background-color: $color2;}.episode {    position: relative;    border-radius: 10px;    overflow: hidden;    padding: 20px 40px;    background-color: $color5;    background-size: cover;    background-position: center;    margin-bottom: 20px;    color: #ffffff;    &:last-child {        margin-bottom: 0;    }}</style>